<div class="container-fluid py-4"><a class="btn btn-outline-secondary mb-3" href="<?= base_url('cliente/servicio_tecnico') ?>">← Volver a solicitudes</a><div class="card mb-4"><div class="card-body"><h2><?= html_escape($servicio->nombre_equipo) ?></h2><p class="mb-1"><strong>Problema:</strong> <?= nl2br(html_escape($servicio->descripcion_problema)) ?></p><p class="mb-1"><strong>Técnico:</strong> <?= !empty($servicio->tecnico_nombre) ? html_escape($servicio->tecnico_nombre.' '.$servicio->tecnico_apellido) : 'Pendiente de asignación' ?></p><p class="mb-0"><strong>Diagnóstico:</strong> <?= !empty($servicio->diagnostico) ? nl2br(html_escape($servicio->diagnostico)) : 'Pendiente de diagnóstico' ?></p></div></div><div class="card"><div class="card-body"><h4>Seguimiento</h4><?php if (!empty($seguimientos)): ?><ul class="list-group list-group-flush"><?php foreach ($seguimientos as $seguimiento): ?><li class="list-group-item"><strong><?= html_escape($seguimiento->estado) ?></strong><br><?= nl2br(html_escape($seguimiento->detalle)) ?><small class="d-block text-muted mt-1"><?= date('d/m/Y H:i',strtotime($seguimiento->fecha_registro)) ?></small></li><?php endforeach ?></ul><?php else: ?><p class="text-muted mb-0">Aún no hay avances registrados.</p><?php endif ?></div></div></div>
